package devrunner

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	v1 "github.com/HardenedLinux/weaver/go/api/v1"
	"io"
	"maps"
	"os"
	"path/filepath"
)

// SpecQualification is generated by the pinned analyzer, never caller verdicts.
type SpecQualification struct {
	Document     []byte
	Digest, Path string
}

// QualifySpec runs real SPEC analysis in the existing development process owner.
// Production request/publication paths do not launch Lean or communicate by CLI.
func QualifySpec(ctx context.Context, root string) (SpecQualification, error) {
	before, err := SourceInputs(root)
	if err != nil {
		return SpecQualification{}, err
	}
	base := filepath.Join(root, ".cache", "spec-qualification")
	if err = os.MkdirAll(base, 0700); err != nil {
		return SpecQualification{}, err
	}
	directory, err := os.MkdirTemp(base, "run-")
	if err != nil {
		return SpecQualification{}, err
	}
	imports := Stage{Name: "spec-qualification-imports", Binary: "elan", Args: []string{"run", proofToolchain, "lake", "-d", "dev/proofs/cedar", "build", "ProviderReview"}}
	analysis := Stage{Name: "spec-exact-delta-qualification", Binary: "elan", Args: []string{"run", proofToolchain, "lake", "-d", "dev/proofs/cedar", "env", "lean", "--run", "dev/proofs/cedar/ReviewQualification.lean"}}
	for _, stage := range []Stage{imports, analysis} {
		result := runStage(ctx, root, directory, os.Environ(), stage)
		if result.Status != "PASS" {
			return SpecQualification{}, fmt.Errorf("SPEC qualification refused: %s: %s", filepath.Join(directory, result.Log), result.Error)
		}
	}
	file, err := os.Open(filepath.Join(directory, analysis.Name+".log"))
	if err != nil {
		return SpecQualification{}, err
	}
	document, err := io.ReadAll(io.LimitReader(file, 65537))
	err = errors.Join(err, file.Close())
	if err != nil {
		return SpecQualification{}, err
	}
	document = bytes.TrimSpace(document)
	if len(document) > 65536 {
		return SpecQualification{}, errors.New("SPEC qualification output bound")
	}
	catalog, err := v1.Decode[v1.QualifiedDeltaCatalog](document)
	if err != nil {
		return SpecQualification{}, err
	}
	if catalog.Engine != "cedar-poo-spec.exact-error-free-allow" || catalog.Qualification != "solver-checked" || len(catalog.Entries) == 0 {
		return SpecQualification{}, errors.New("SPEC qualification protocol")
	}
	after, err := SourceInputs(root)
	if err != nil {
		return SpecQualification{}, err
	}
	if !maps.Equal(before, after) {
		return SpecQualification{}, errors.New("sources changed during SPEC qualification")
	}
	path := filepath.Join(directory, "catalog.json")
	if err = os.WriteFile(path, document, 0600); err != nil {
		return SpecQualification{}, err
	}
	digest := sha256.Sum256(document)
	return SpecQualification{Document: document, Digest: hex.EncodeToString(digest[:]), Path: path}, nil
}
